/**
 * Module declaration for `@wails-bindings`.
 *
 * The Vite alias maps this specifier to the file generated by
 * `wails3 generate bindings -ts` (wails/frontend/bindings/droidgear-wails/
 * internal/app/app.ts). That generated file lives outside the TypeScript
 * project (tsconfig includes only `src/`), so its exact shape is not
 * re-declared here; `tauri-core.ts` casts the namespace to a method
 * registry and selects Go service methods by name.
 */
declare module '@wails-bindings' {
  export {}
}
